import sys
from collections import defaultdict, deque

def expected_time_to_exit(N, M, paths):
    # Create adjacency list for the graph
    graph = defaultdict(list)
    for K, L in paths:
        graph[K].append(L)
        graph[L].append(K)

    # Breadth-first search to determine shortest path distances to exit
    distances = [-1] * N
    queue = deque([(N - 1, 0)])
    distances[N - 1] = 0

    while queue:
        node, dist = queue.popleft()
        for neighbor in graph[node]:
            if distances[neighbor] == -1:
                distances[neighbor] = dist + 1
                queue.append((neighbor, dist + 1))

    # Expectation calculation
    def dfs(node, visited):
        if node == N - 1:
            return 0
        visited.add(node)
        total_time = 0
        num_neighbors = 0
        for neighbor in graph[node]:
            if neighbor not in visited:
                num_neighbors += 1
                total_time += dfs(neighbor, visited)
        visited.remove(node)
        return 1 + (total_time / num_neighbors) if num_neighbors > 0 else float('inf')

    return dfs(0, set())

def main():
