from collections import defaultdict

def solve():
    N, M = map(int, input().split())
    graph = defaultdict(list)

    for _ in range(M):
        K, L = map(int, input().split())
        graph[K].append(L)
        graph[L].append(K)

    def dfs(node, parent):
        if node == N - 1:
            return 1

        total = 0
        for neighbor in graph[node]:
            if neighbor != parent:
                total += dfs(neighbor, node)

        if node == 0:
            return total / len(graph[node])
        else:
            return (total + 1) / len(graph[node])

    result = dfs(0, -1)
    print(f"{result:.6f}")

